/**
 * Concatenates src/api/sql/*.sql into schema_full.sql and bundledSchema.ts
 * Run: npm run bundle-sql
 */
const fs = require("fs");
const path = require("path");

const SQL_DIR = path.join(__dirname, "..", "src", "api", "sql");
const PARTS = [
  "00_pragmas.sql",
  "01_schema.sql",
  "02_indexes.sql",
  "03_seed_reference.sql",
];
const DROP_FILE = "99_drop_all.sql";

function readPart(filename) {
  return fs.readFileSync(path.join(SQL_DIR, filename), "utf8").trim();
}

const pragmas = readPart("00_pragmas.sql");
const schema = readPart("01_schema.sql");
const indexes = readPart("02_indexes.sql");
const seed = readPart("03_seed_reference.sql");
const dropAll = readPart(DROP_FILE);

const bootstrap = [pragmas, schema, indexes, seed].join("\n\n");
const schemaFull = `-- Generated by scripts/bundle-sql.js — do not edit by hand\n-- Edit src/api/sql/*.sql and run: npm run bundle-sql\n\n${bootstrap}\n`;

fs.writeFileSync(path.join(SQL_DIR, "schema_full.sql"), schemaFull, "utf8");

const tsContent = `// Generated by scripts/bundle-sql.js — do not edit by hand
// Edit src/api/sql/*.sql and run: npm run bundle-sql

export const SCHEMA_VERSION = 1;

export const SQL_PRAGMAS = ${JSON.stringify(pragmas)};

export const SQL_SCHEMA = ${JSON.stringify(schema)};

export const SQL_INDEXES = ${JSON.stringify(indexes)};

export const SQL_SEED = ${JSON.stringify(seed)};

export const SQL_DROP_ALL = ${JSON.stringify(dropAll)};

/** PRAGMA + tables + indexes + seed (idempotent bootstrap) */
export const SQL_BOOTSTRAP = ${JSON.stringify(bootstrap)};
`;

fs.writeFileSync(path.join(SQL_DIR, "bundledSchema.ts"), tsContent, "utf8");

console.log("Wrote src/api/sql/schema_full.sql");
console.log("Wrote src/api/sql/bundledSchema.ts");
